\begin{lemma}[Symmetrization of strategies for symmetric games]\label{lem:symmetric-strat}
	\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy_approx}
	\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy_of_lt_value}
	\leanok
	\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general, lem:symmetric-strat-given-strategy}
	\emph{Corrected statement.} Let $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ be a symmetric game whose answer alphabet $\mathcal A$ is nonempty, and suppose $\operatorname{val}^*(\mathfrak G) = 1-\eps$ for some $\eps \ge 0$. Then for every $\eps' > \eps$ there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ such that
	\[
		\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps'\,.
	\]
	Equivalently, for every slack $\delta > 0$ there is a symmetric projective strategy of value at least $\operatorname{val}^*(\mathfrak G) - \delta$; that slack form is the Lean declaration \texttt{exists\_symmetric\_projective\_strategy\_of\_lt\_value}.

	The source prints the conclusion at $\eps' = \eps$, that is, with the supremum attained. That form is not established by the argument below and is false on the Lean domain, which admits an empty answer alphabet; it is stated and analyzed in Remark~\ref{rem:symmetric-strat-limit} and in \cite{gap:qpbt_symmetrization-attainment}. The nonemptiness of $\mathcal A$ is the source's standing convention, displayed here because the formal domain does not impose it.
\end{lemma}
\begin{proof}
	\leanok
	\uses{thm:naimark, lem:symmetric-strat-given-strategy}
	Fix $\eps' > \eps$. Since $\operatorname{val}^*(\mathfrak G)$ is the supremum of the values of all strategies, there exists a strategy $\mathcal S' = (\ket{\psi'}, A, B)$ with $\operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. (In the formalization this step is where nonemptiness of $\mathcal A$ is used: it supplies the one-dimensional strategy answering a fixed answer deterministically, so the set of strategy values is nonempty, and that set is bounded above by $1$, so $\operatorname{val}^*(\mathfrak G)$ is a genuine least upper bound and the supremum property applies. With an empty answer alphabet there is no strategy at all, while $\operatorname{val}^*(\mathfrak G)$ is still defined as the totalized supremum of the empty set.) Using Naimark dilation (Theorem~\ref{thm:naimark}), each dilated sub-measurement being completed to a projective measurement by assigning to one fixed outcome the residual projector of its family --- which changes no correlation on the extended state, as described in Remark~\ref{rem:naimark-for-games} above --- we may assume without loss of generality that $\ket{\psi'} \in \C^d_{A'} \ot \C^d_{B'}$ for some integer $d$ and that every $A^x$ and $B^x$ is a projective measurement. Let
	\[
		\ket{\psi} = \frac{1}{\sqrt 2}\, \bigl( \ket{0}_{A}\ket{1}_{B}\ket{\psi'}_{A'B'} + \ket{1}_{A}\ket{0}_{B}\ket{\psi'_\tau}_{A'B'} \bigr) \in \bigl(\C^2_{A} \ot \C^d_{A'}\bigr) \ot \bigl(\C^2_{B} \ot \C^d_{B'}\bigr)\,,
	\]
	where $\ket{\psi'_\tau}$ is obtained from $\ket{\psi'}$ by permuting the two players' registers; then $\ket{\psi}$ is invariant under permutation of the register pairs $AA'$ and $BB'$. For each question $x \in \mathcal X$ define the projective measurement $M^x = \{M^x_a\}_{a \in \mathcal A}$ on $\C^2 \ot \C^d$ by
	\[
		M^x_a = \ket{0}\bra{0} \ot A^x_a + \ket{1}\bra{1} \ot B^x_a\,,
	\]
	and let each player measure $M$ on their pair of registers. Because the decision predicate $D$ of the symmetric game treats the two players symmetrically, the resulting symmetric projective strategy $\mathcal S = (\ket{\psi}, M)$ satisfies $\operatorname{val}^*(\mathfrak G, \mathcal S) = \operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Note that this construction preserves the value of the strategy it is applied to exactly.

	This proves the corrected statement. It does not prove the printed one, which asserts a single symmetric projective strategy of value at least $1-\eps$ itself; see Remark~\ref{rem:symmetric-strat-limit}.
\end{proof}

% The printed source sentence is preserved here and, in Lean, as the unasserted
% proposition MIPStarRE.QPBT.PrintedSymmetricProjectiveAttainmentClaim, whose universally
% quantified form is refuted by
% MIPStarRE.QPBT.not_forall_printedSymmetricProjectiveAttainmentClaim.
\begin{remark}[The printed attainment form of the symmetrization lemma]\label{rem:symmetric-strat-limit}
	The source prints Lemma~\ref{lem:symmetric-strat} in the following stronger form (\path{references/qpbt-paper/06_nonlocal_games_and_mipstar.tex}, lines~94--99): if $\mathfrak G$ is a symmetric game with $\operatorname{val}^*(\mathfrak G) = 1-\eps$ for some $\eps \ge 0$, then there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ with $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps$. This development does not assert that sentence anywhere. It is recorded verbatim, and unasserted, as the Lean proposition \texttt{PrintedSymmetricProjectiveAttainmentClaim}.

	Two independent defects separate it from the corrected statement. First, the argument of Lemma~\ref{lem:symmetric-strat} yields, for each $\eps' > \eps$, a symmetric projective strategy of value at least $1-\eps'$, and the conclusion at $\eps' = \eps$ does not follow: the dilated dimension $d$ may grow as $\eps' \downarrow \eps$, and the supremum defining $\operatorname{val}^*(\mathfrak G)$ in Definition~\ref{def:tensor-product-value} need not be attained by any strategy. Second, on the formal domain the printed sentence is false: Definition~\ref{def:symmetric-game} permits an empty answer alphabet, for which no strategy exists at all while $\operatorname{val}^*(\mathfrak G)$ is still defined as the totalized supremum of the empty set, so the hypotheses hold at $\eps = 1$ and the conclusion has no witness. The Lean declaration \texttt{not\_forall\_printed\-Symmetric\-Projective\-Attainment\-Claim} proves exactly this refutation of the universally quantified printed claim.

	Nothing downstream is lost. The symmetrization construction is value-preserving, so the printed conclusion does hold whenever the hypothesis supplies an actual strategy of value at least $1-\eps$ rather than only the value of the game; that is Lemma~\ref{lem:symmetric-strat-given-strategy}. Every use of the lemma in the source proceeds from such a strategy, or from a strict lower bound on the value, and therefore consumes only what the corrected statement provides. The full analysis, including the kernel-checked empty-answer counterexample, is in \cite{gap:qpbt_symmetrization-attainment}.
\end{remark}

% This node is not a statement of the paper: it is the Lean record of the printed
% sentence, kept so that the discrepancy stays visible and machine-checked, together
% with its refutation on the current formal domain.
\begin{lemma}[The printed attainment claim, recorded and refuted]
	\label{lem:symmetric-strat-printed-claim}
	\lean{MIPStarRE.QPBT.PrintedSymmetricProjectiveAttainmentClaim}
	\lean{MIPStarRE.QPBT.not_forall_printedSymmetricProjectiveAttainmentClaim}
	\leanok
	\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}
	This formalization-only node is not a named statement of the paper. It records the printed sentence of Remark~\ref{rem:symmetric-strat-limit} as a proposition $\mathrm{PrintedAttainment}(\mathfrak G, \eps)$ --- namely, ``$\eps \ge 0$ and $\operatorname{val}^*(\mathfrak G) = 1-\eps$ imply that some symmetric projective strategy $\mathcal S$ has $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps$'' --- without asserting it, and states its refutation: it is \emph{not} the case that $\mathrm{PrintedAttainment}(\mathfrak G, \eps)$ holds for every symmetric game $\mathfrak G$ and every real $\eps$.
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:symmetric-game, def:tensor-product-value}
	Take $\mathfrak G$ with one question, empty answer alphabet, the uniform distribution on the single question pair, and the unique decision predicate on the empty answer domain; both symmetry conditions hold. A unit vector in $\hilb_A \ot \hilb_B$ forces both local index types to be nonempty, while completeness of an empty measurement on a nonzero space would equate $0$ with the identity, so $\mathfrak G$ has no strategy at all. The set of strategy values is therefore empty and $\operatorname{val}^*(\mathfrak G) = 0$ by the totalization convention for the real conditional supremum of the empty set. At $\eps = 1$ both hypotheses of $\mathrm{PrintedAttainment}(\mathfrak G, 1)$ hold and its conclusion has no witness. This refutes the printed claim over the formal domain only; it settles nothing about attainment for symmetric games with nonempty answer alphabets, for which the unattained-supremum obstruction of Remark~\ref{rem:symmetric-strat-limit} is the operative one. See \cite{gap:qpbt_symmetrization-attainment}.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:symmetric-strat}]
	\label{lem:symmetric-strat-given-strategy}
	\lean{MIPStarRE.QPBT.exists_symmetric_projective_strategy_of_strategy}
	\leanok
	\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}
	This formalization-only auxiliary is not a named statement of the paper; it is the value-preserving given-strategy form of Lemma~\ref{lem:symmetric-strat} isolated in Remark~\ref{rem:symmetric-strat-limit}, and it is what the symmetrization argument actually proves. Let $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ be a symmetric game and let $\mathcal S'$ be a strategy for $\mathfrak G$ with $\operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps$. Then there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ with
	\[
		\operatorname{val}^*(\mathfrak G, \mathcal S) = \operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{thm:naimark}
	Apply Naimark dilation (Theorem~\ref{thm:naimark}) to $\mathcal S'$, completing each dilated family at one fixed outcome as described in Remark~\ref{rem:naimark-for-games}, and then form the permutation-invariant state $\ket{\psi}$ and the block-diagonal measurements $M^x$ of the proof of Lemma~\ref{lem:symmetric-strat}. Both steps preserve the value of the strategy they are applied to, so $\mathcal S$ has exactly the value of $\mathcal S'$. No attainment step is involved, since the strategy $\mathcal S'$ is given rather than extracted from the supremum defining $\operatorname{val}^*(\mathfrak G)$.
\end{proof}

\begin{definition}[Commuting strategies]\label{def:comm-strategy}
	\lean{MIPStarRE.QPBT.IsCommutingOn, MIPStarRE.QPBT.Strategy.IsCommuting}
	\leanok
	\uses{def:game, def:tensor-product-strategy}
	Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a game, and let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy for $\mathfrak G$ such that $\mathcal H_A = \mathcal H_B$. We say that $\mathcal S$ is a \emph{commuting strategy for $\mathfrak G$} if for all question pairs $(x,y)$ in the support of $\mu$ (i.e.\ all $(x,y)$ with $\mu(x,y) > 0$) we have
	\[
		[A^x_a, B^y_b] = 0 \qquad \text{for all } a \in \mathcal A,\ b \in \mathcal B\,,
	\]
	where $[A,B] = AB - BA$ denotes the commutator.
\end{definition}

\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
	\lean{MIPStarRE.QPBT.Measurement.IsConsistentOn}
	\leanok
	\uses{def:povm-conventions}
	Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
	\[
		\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
	\]
	When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
\end{definition}

The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
\[
	\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
\]
where the first equality is by the definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a = \Id$.

