	\leanok
	For $C\geq1$ and $0\leq\eta,\delta\leq1$, set
	\[
		K=C\delta+(2\sqrt{2\delta}+2\delta+2\sqrt{C\delta}+C\delta)
		  +2\eta+2\sqrt{2(\delta+2\sqrt{2\delta}+\eta)}
		  +2\sqrt{2(\delta+2\sqrt{2\delta})}.
	\]
	Then $2\delta+\sqrt K\leq(3C+19)(\eta^{1/4}+\delta^{1/8})$.
	This is a formalization-only scalar estimate for Lemma~\ref{lem:pasting}.
\end{lemma}
\begin{proof}
	\leanok
	Put $u=\delta^{1/8}$ and $v=\eta^{1/4}$. Both lie in $[0,1]$.
	Bound the successive square roots using these variables and compare
	the resulting nonnegative polynomials.
\end{proof}

\begin{lemma}[Paired-entry estimate for the Schmidt mirror]
	\label{lem:pasting-schmidt-pair}
	\lean{MIPStarRE.QPBT.schmidt_pair_mirror_estimate}
	\leanok
	For $s,t\geq0$ and $u,v\in\mathbb C$,
