\begin{lemma}[Schmidt coordinates for a square coefficient matrix]
	\label{lem:pasting-schmidt-coordinates}
	\lean{MIPStarRE.QPBT.exists_schmidt_coordinates, MIPStarRE.QPBT.schmidtCoordinates_spec}
	\leanok
	Every square complex matrix $C$ has a decomposition
	$C=U\operatorname{diag}(s_i)V^*$ with unitary $U,V$ and $s_i\geq0$.
	Zero singular values are allowed. This is a formalization-only construction
	for the argument in \cite{gap:qpbt_pasting-product-error}.
\end{lemma}
\begin{proof}
	\leanok
	Diagonalize $C^*C$, normalize the images of its positive-eigenvalue
	eigenvectors, and complete this orthonormal family on the left. The
	zero-eigenvalue eigenvectors are annihilated by $C$.
\end{proof}

\begin{definition}[The state-dependent Schmidt mirror]
	\label{def:pasting-schmidt-mirror}
	\lean{MIPStarRE.QPBT.schmidtCoefficientMatrix, MIPStarRE.QPBT.schmidtCoordinates, MIPStarRE.QPBT.schmidtMirrorUnitary, MIPStarRE.QPBT.schmidtMirror}
	\leanok
	\uses{lem:pasting-schmidt-coordinates}
	For any bipartite vector $\psi$, form its coefficient matrix
	$C_{ij}=\psi_{ij}$ and choose Schmidt coordinates
	$C=U\operatorname{diag}(s_i)V^*$ once for that vector. For a Bob operator
	$B$, define the Alice operator
	$\widetilde B=UV^*B^TVU^*$.
	This auxiliary operator does not replace any measurement in the statement
	of Lemma~\ref{lem:pasting}.
\end{definition}

\begin{lemma}[Schmidt-mirror norm estimate]
	\label{lem:pasting-schmidt-mirror-norm}
	\lean{MIPStarRE.QPBT.schmidt_diagonal_mirror_estimate, MIPStarRE.QPBT.schmidt_action_norm_sq, MIPStarRE.QPBT.schmidtMirror_norm_sq_le}
	\leanok
	\uses{def:pasting-schmidt-mirror, lem:pasting-schmidt-pair}
	For every bipartite vector $\psi$ and Hermitian operators $H,B$,
	\[
		\|(\widetilde B\ot\Id-\Id\ot B)\psi\|^2
		\leq 2\|(H\ot\Id-\Id\ot B)\psi\|^2.
	\]
	Neither normalization nor invertibility of the reduced state is needed.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:pasting-schmidt-coordinates, lem:pasting-schmidt-pair}
	Vectorization identifies the squared Hilbert norm with the sum of squared
	moduli of the coefficient-matrix entries. Unitary changes of basis preserve
	this sum. In Schmidt coordinates, pair the entries $(i,j)$ and $(j,i)$
	and apply Lemma~\ref{lem:pasting-schmidt-pair}.
\end{proof}

\begin{lemma}[Mirrored measurements]
	\label{lem:pasting-schmidt-mirror-measurement}
	\lean{MIPStarRE.QPBT.schmidtMirror_one, MIPStarRE.QPBT.schmidtMirror_mul, MIPStarRE.QPBT.schmidtMirror_adjoint, MIPStarRE.QPBT.schmidtMirror_posSemidef, MIPStarRE.QPBT.schmidtMirrorMeasurement, MIPStarRE.QPBT.schmidtMirrorMeasurement_postprocess, MIPStarRE.QPBT.schmidtMirrorMeasurement_isProjective}
	\leanok
	\uses{def:pasting-schmidt-mirror, def:povm-conventions}
	The mirror is linear, unital, adjoint-preserving, positive, and satisfies
	$\widetilde{B_1B_2}=\widetilde B_2\widetilde B_1$.
	It maps measurements to measurements and projective measurements to
	projective measurements, and commutes with every outcome coarse-graining.
\end{lemma}
\begin{proof}
	\leanok
	These properties follow from transposition and unitary conjugation.
	Completeness and coarse-graining follow by linearity; idempotence is
	preserved despite the reversal of multiplication.
\end{proof}

\begin{lemma}[Cross move with independent opposite-register effects]
	\label{lem:pasting-distinct-cross-move}
	\lean{MIPStarRE.QPBT.abs_cross_move_gap_le_sqrt_distinct_families}
	\leanok
	\uses{def:pasting-tensor-placement, def:povm-conventions}
	Let $P,G,H$ be measurements, with $G,H$ indexed by the same codewords,
	and let $\psi$ be a unit vector. Then
	\begin{align*}
	 &\left|\operatorname{Re}\sum_{a,g}\langle\psi|\Id\ot G_gP_aG_gP_a|\psi\rangle
	   -\operatorname{Re}\sum_{g,a}\langle\psi|H_g\ot P_aG_gP_a|\psi\rangle\right|\\
	 &\qquad\leq
	 \sqrt{\sum_g\|(\Id\ot G_g-H_g\ot\Id)\psi\|^2}.
	\end{align*}
	No equality between the two codeword families is assumed.
\end{lemma}
\begin{proof}
	\leanok
	Expand the difference as an inner product of the moved vectors with the
	cross vectors. Measurement contraction and Cauchy--Schwarz give the bound.
\end{proof}

\begin{lemma}[Collision bounds for independent opposite-register families]
	\label{lem:pasting-distinct-collisions}
	\lean{MIPStarRE.QPBT.consistencyDefect_codeword_fine_le_coarse_add_distinct_families, MIPStarRE.QPBT.avgOver_pinched_collision_le_distinct_families}
	\leanok
	\uses{lem:pasting-collision-averaging, def:povm-conventions}
	Let $G^x,H^x$ be measurements indexed by the same second codewords,
	let $P^{x,y_1}$ be a measurement, and let $\psi$ be a unit vector.
	Assume a probability law $\mathcal D$ and the conditional collision bound
	of Lemma~\ref{lem:pasting}, with $\eta\geq0$.
	The fine consistency defect between $H$ on Alice and $G$ on Bob is at most
	the corresponding coarse defect plus $\eta$. Moreover,
	\[
	 \E_{\mathcal D}\sum_{g\ne h:\,g(y_2)=h(y_2)}\sum_a
	 \langle\psi|H^x_h\ot P^{x,y_1}_aG^x_gP^{x,y_1}_a|\psi\rangle
	 \leq\eta.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:pasting-collision-averaging}
	The summands are nonnegative and have total mass at most one.
	They are independent of $y_2$ after conditioning on $(x,y_1)$.
	Apply the conditional collision bound to each off-diagonal codeword pair.
\end{proof}

\begin{lemma}[Averaged Schmidt-mirror consistency]
	\label{lem:pasting-schmidt-mirror-consistency}
	\lean{MIPStarRE.QPBT.consistencyDefect_schmidtMirror_le}
	\leanok
	\uses{lem:pasting-schmidt-mirror-norm, lem:pasting-schmidt-mirror-measurement,
		fact:agreement}
	For a finite question distribution, any vector $\psi$, any measurement
	family $A$, and any projective family $B$, the consistency defect between
	$\widetilde B$ on Alice and $B$ on Bob is at most twice that between
	$A$ on Alice and $B$ on Bob. In particular the second forward comparison
	of Lemma~\ref{lem:pasting} gives coarse mirror consistency at most $2\delta$.
\end{lemma}
\begin{proof}
	\leanok
	Sum the mirror norm estimate over answers and average over questions.
	The mirror and Bob are projective, so their squared distance is twice
	their consistency defect. The predictor's squared distance is at most
	twice its consistency defect even without projectivity.
\end{proof}

\begin{lemma}[Fine commutators with an independent opposite-register family]
	\label{lem:pasting-distinct-fine-commutator}
	\lean{MIPStarRE.QPBT.pinched_coarse_sub_fine_eq_distinct_families, MIPStarRE.QPBT.commutator_mass_fine_le_distinct_families}
	\leanok
	\uses{lem:pasting-distinct-cross-move, lem:pasting-distinct-collisions,
		lem:pasting-commutator-expansion, lem:pasting-ordered-product-mass}
	Let $G^x$ be projective Bob measurements, $H^x$ any measurements on Alice
	with the same codeword labels, and $P^{x,y_1}$ any measurement family.
	Under the conditional collision assumption and for a unit vector, suppose
	the coarse commutator mass is at most $K_0$, the coarse ordered-product
	mass is at least $1-m$, and the coarse and fine squared distances between
	$G$ on Bob and $H$ on Alice are at most $e_c,e_f$ on average. Then
	\[
	 K_{\mathrm{fine}}\leq K_0+m+2\eta+2\sqrt{e_f}+2\sqrt{e_c}.
	\]
	Pointwise, the coarse pinched cross term minus the fine one is exactly
	\[
	 \sum_{g\ne h:\,g(y_2)=h(y_2)}\sum_a
	 \langle\psi|H^x_h\ot P^{x,y_1}_aG^x_gP^{x,y_1}_a|\psi\rangle.
	\]
\end{lemma}
\begin{proof}
	\leanok
	Expand the four commutator terms. The reversed-product masses agree,
	and the ordered-product masses differ by at most $m$.
	Move the rightmost effect in each cross term to $H$ on Alice, paying
	$\sqrt{e_f}$ and $\sqrt{e_c}$. The fiber expansion gives the displayed
	collision identity, whose averaged right side is at most $\eta$.
\end{proof}

\begin{lemma}[One-sided explicit pasting estimate]
	\label{lem:pasting-one-sided-explicit-error}
	\lean{MIPStarRE.QPBT.consistencyDefect_pasted_le_sqrt_one_sided}
	\leanok
	\uses{lem:pasting-schmidt-mirror-consistency, lem:pasting-distinct-collisions,
		lem:pasting-distinct-fine-commutator, lem:pasting-ordered-product-mass-lower,
		lem:pasting-pinched-reduction, lem:pasting-pinched-cauchy-schwarz}
	In the setting of Lemma~\ref{lem:pasting}, joint self-consistency may be
	omitted for this estimate. Assume $0\leq\delta\leq1$ and a coarse
	commutator bound $K_0\leq C\delta$. Set
	\begin{align*}
	 m&=2\sqrt{2\delta}+2\delta+2\sqrt{C\delta}+C\delta,\qquad
	 t=\delta+2\sqrt{2\delta},\\
	 K&=C\delta+m+2\eta+2\sqrt{2(t+\eta)}+2\sqrt{2t}.
	\end{align*}
	Then the pasted consistency defect is at most $2\delta+\sqrt K$.
\end{lemma}
\begin{proof}
	\leanok
	The coarse mirror defect is at most $2\delta\leq t$ on the stated
	interval, and the fine mirror defect is at most $t+\eta$.
	Consistency bounds squared distance by twice the defect. Apply the
	distinct-family commutator comparison with the ordered-product mass bound,
	then the pinched reduction. No reversed marginal comparison is used.
\end{proof}

